-- Після перевірки NULL та існування замовлення:
select nvl(sum(quantity * unit_price), 0)
  into l_total
  from s2_order_items
 where order_id = p_order_id;

-- Для виплати після перевірки статусу:
if l_status = 'CANCELLED' then
  return 0;
end if;
return round(order_total(p_order_id) * (1 - c_fee_rate), 2);

